import React, { useState, useEffect, useCallback } from "react";

// --- CDBI AI Core Global Types and Interfaces (Self-contained) ---

/**
 * Represents a Key Performance Indicator (KPI) generated by CDBI AI.
 */
export interface AICDBIKPI {
  id: string;
  name: string;
  value: number | string;
  unit?: string;
  trend?: "up" | "down" | "neutral";
  insight: string; // AI-generated explanation or recommendation
  color?: string; // For visual representation
}

/**
 * Represents data for a chart generated by CDBI AI.
 */
export interface AICDBIChartDataPoint {
  label: string;
  value: number;
}

export interface AICDBIChart {
  id: string;
  title: string;
  type: "bar" | "line" | "pie" | "text-summary"; // Simplified types, could be expanded
  data: AICDBIChartDataPoint[];
  insight: string; // AI-generated summary or interpretation of the chart
}

/**
 * Represents comprehensive AI insights for a given context (e.g., a page).
 */
export interface AICDBIContextualInsights {
  pageTitle: string;
  summary: string; // AI-generated summary of the page's purpose/content implications
  kpis: AICDBIKPI[];
  charts: AICDBIChart[];
  recommendations: string[]; // Actionable recommendations from AI
  lastUpdated: string; // Timestamp
}

// --- CDBI AI Engine Simulation (Self-contained, represents Gemini interaction) ---

